// Added NeoStar to the imports to fix the "Cannot find name 'NeoStar'" error
import { NeoSkateboard, NeoButterfly, NeoSparkles, NeoSneaker, NeoCassette, NeoFire, NeoBag, NeoGhost, NeoBot, NeoStar } from './components/NeoIcons';
import { Button } from './components/Button';

const CATEGORY_ICONS: Record<string, React.FC<{className?: string}>> = {
  'skateboard': NeoSkateboard,
  'butterfly': NeoButterfly,
  'sparkles': NeoSparkles,
  'sneaker': NeoSneaker,
  'cassette': NeoCassette
};

const ITEM_TYPES = ['Top', 'Bottom', 'Outerwear', 'Shoes', 'Dress', 'Accessory'];

const App: React.FC = () => {
  const [user, setUser] = useState<UserType | null>(null);
  const [hasCompletedOnboarding, setHasCompletedOnboarding] = useState(false);
  const [authLoading, setAuthLoading] = useState(true);
  const [showSplash, setShowSplash] = useState(true);

  const [activeTab, setActiveTab] = useState<Tab>(Tab.HOME);
  const [isUploadOpen, setIsUploadOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isFilterOpen, setIsFilterOpen] = useState(false);
  const [isAiChatOpen, setIsAiChatOpen] = useState(false);

  const [isPaymentOpen, setIsPaymentOpen] = useState(false);
  const [pendingPaymentOrder, setPendingPaymentOrder] = useState<Order | null>(null);

  const [posts, setPosts] = useState<Post[]>(MOCK_POSTS);
  const [cart, setCart] = useState<Post[]>([]);
  const [orders, setOrders] = useState<Order[]>(MOCK_ORDERS);
  const [qnaPairs, setQnaPairs] = useState<QnAPair[]>([]);
  const [savedPostIds, setSavedPostIds] = useState<string[]>([]);

  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState<string | null>(null);

  const [filters, setFilters] = useState<{ 
    sort: string; 
    size: string[]; 
    brand: string[];
    category: string[];
    color: string[];
  }>({
    sort: 'newest',
    size: [],
    brand: [],
    category: [],
    color: []
  });

  const [activeAskPost, setActiveAskPost] = useState<Post | null>(null);
  const [activeOfferPost, setActiveOfferPost] = useState<Post | null>(null);
  const [viewingPost, setViewingPost] = useState<Post | null>(null);

  useEffect(() => {
    const timer = setTimeout(() => {
      setShowSplash(false);
    }, 1800);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    let mounted = true;

    const timeoutId = setTimeout(() => {
      if (mounted && authLoading) {
        setAuthLoading(false);
      }
    }, 5000);

    const initAuth = async () => {
      try {
        if (!auth || typeof auth.onAuthStateChanged !== 'function') {
           if (mounted) setAuthLoading(false);
           return;
        }

        auth.onAuthStateChanged(async (firebaseUser: any) => {
          if (!mounted) return;

          if (firebaseUser) {
            try {
              if (isMock) {
                   const userData: UserType = {
                      id: firebaseUser.uid,
                      username: firebaseUser.displayName || 'Guest',
                      displayName: firebaseUser.displayName || 'Guest',
                      avatarUrl: firebaseUser.photoURL || 'https://picsum.photos/200',
                      isVerified: false,
                      isSellerEligible: true,
                      sustainabilityScore: 0,
                      phoneVerified: false,
                      kycStatus: 'none',
                      sellerRating: 0,
                      totalSales: 0,
                      savedPostIds: [],
                      isAdmin: false
                   };
                   setUser(userData);
                   setHasCompletedOnboarding(true); 
              } else {
                  const userDocRef = db.collection('users').doc(firebaseUser.uid);
                  const userDoc = await userDocRef.get();

                  if (userDoc.exists) {
                    const userData = userDoc.data() as UserType;
                    setUser(userData);
                    setSavedPostIds(userData.savedPostIds || []);
                    setHasCompletedOnboarding(true);
                  } else {
                     const newUser: UserType = {
                      id: firebaseUser.uid,
                      username: '',
                      displayName: firebaseUser.displayName || '',
                      avatarUrl: firebaseUser.photoURL || '',
                      isVerified: false,
                      isSellerEligible: false,
                      sustainabilityScore: 0,
                      phoneVerified: false,
                      kycStatus: 'none',
                      sellerRating: 0,
                      totalSales: 0,
                      savedPostIds: []
                    };
                    setUser(newUser);
                    setHasCompletedOnboarding(false);
                  }
              }
            } catch (e) {
              setUser(null);
            }
          } else {
            setUser(null);
          }
          setAuthLoading(false);
        });
      } catch (err) {
        if (mounted) setAuthLoading(false);
      }
    };

    initAuth();

    return () => {
      mounted = false;
      clearTimeout(timeoutId);
    };
  }, []);

  const createDemoUser = (ageEligibleForPayouts: boolean, data?: { phoneNumber?: string, isSignup?: boolean }) => {
