        return (
            <div className="relative">
                 <button onClick={handleLogout} className="absolute top-6 left-6 z-20 bg-white/20 backdrop-blur p-2 rounded-full hover:bg-white/40 text-white transition-colors"><LogOut className="w-5 h-5"/></button>
                 <Profile 
                    user={user!} 
                    posts={posts} 
                    savedPosts={savedPostsList}
                    onOpenDashboard={() => setActiveTab(Tab.SELLER_DASHBOARD)} 
                    onOpenOrderTracking={() => setActiveTab(Tab.ORDER_TRACKING)}
                    onOpenSettings={() => setIsSettingsOpen(true)}
                    onPostClick={setViewingPost}
                 />
            </div>
        );
      default:
        return null;
    }
  };

  return (
    <Layout 
      activeTab={activeTab} 
      onTabChange={setActiveTab} 
      onOpenUpload={() => setIsUploadOpen(true)} 
      cartCount={cart.length}
    >
      {renderTabContent()}
      {viewingPost && (
          <ProductDetail 
            post={viewingPost}
            onClose={() => setViewingPost(null)}
            onAddToCart={handleAddToCart}
            onBuyNow={(p) => {
                handleAddToCart(p);
                setActiveTab(Tab.CART);
                setViewingPost(null);
            }}
            onMakeOffer={(p) => {
                setViewingPost(null);
                setActiveOfferPost(p);
            }}
            isSaved={savedPostIds.includes(viewingPost.id)}
            onToggleSave={handleToggleSave}
          />
      )}
      <UploadModal isOpen={isUploadOpen} onClose={() => setIsUploadOpen(false)} onPost={handlePost} />
      <AskModal isOpen={!!activeAskPost} onClose={() => setActiveAskPost(null)} post={activeAskPost} onSubmit={handleAskQuestion} />
      {activeOfferPost && (
          <OfferModal 
            isOpen={!!activeOfferPost} 
            onClose={() => setActiveOfferPost(null)} 
            post={activeOfferPost} 
            onSubmit={handleMakeOffer} 
          />
      )}
      {user && (
          <ProfileSettingsModal 
            isOpen={isSettingsOpen} 
            onClose={() => setIsSettingsOpen(false)} 
            currentUser={user} 
            onUpdateUser={handleUpdateProfile} 
          />
      )}
      <FilterModal 
        isOpen={isFilterOpen}
        onClose={() => setIsFilterOpen(false)}
        availableSizes={availableSizes}
        availableBrands={availableBrands}
        availableCategories={ITEM_TYPES}
        availableColors={availableColors}
        currentFilters={filters}
        onApply={setFilters}
      />
      <PaymentModal 
        isOpen={isPaymentOpen}
        onClose={() => setIsPaymentOpen(false)}
        totalAmount={pendingPaymentOrder ? (pendingPaymentOrder.totalAmount || 0) : cart.reduce((sum, item) => sum + item.price, 0)}
        onComplete={handlePaymentComplete}
      />
      {!isUploadOpen && !isAiChatOpen && !isSettingsOpen && !isFilterOpen && !isPaymentOpen && !viewingPost && activeTab !== Tab.CHALLENGES && (
        <button
            onClick={() => setIsAiChatOpen(true)}
            className="fixed bottom-28 right-4 z-40 w-12 h-12 bg-earth-900 text-white rounded-full shadow-xl flex items-center justify-center border-2 border-white hover:scale-110 transition-transform active:scale-95 animate-bounce-in"
        >
            <NeoBot className="w-6 h-6" />
        </button>
      )}
      <AiChatModal isOpen={isAiChatOpen} onClose={() => setIsAiChatOpen(false)} />
    </Layout>
  );
};

export default App;

