import { GoogleGenAI } from "@google/genai";

// Initialize with a fallback to avoid crashing on module load if API_KEY is missing
const getAiClient = () => {
  const apiKey = process.env.API_KEY || "";
  return new GoogleGenAI({ apiKey });
};

export const generateCreativeCaption = async (
  itemType: string,
  vibe: string,
  details: string
): Promise<string> => {
  try {
    const ai = getAiClient();
    const prompt = `
      You are a Gen Z fashion influencer from India on a social thrift app called "Revendre".
      Write a short, catchy, "Hinglish" (Hindi + English mix) caption for selling a fashion item.

      Item: ${itemType}
      Aesthetic/Vibe: ${vibe}
      Specific Details: ${details}

      Rules:
      1. Use Gen Z slang (e.g., "drip", "cop", "scene", "yaar", "mast").
      2. Keep it under 280 characters.
      3. Include 3 relevant hashtags.
      4. Make it sound enthusiastic and authentic, not like a robot.
      5. Highlight the material/color if provided to sound like an expert.
      6. Mention "Refreshed by Revendre" subtly if it sounds premium.

      Output JUST the caption text.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return (response.text || "").trim();
  } catch (error) {
    console.error("Error generating caption:", error);
    return "Fresh fit alert! 🚨 Cop this before it's gone. #ThriftFinds";
  }
};

export const chatWithGemini = async (
  message: string,
  history: { role: 'user' | 'model'; text: string }[]
): Promise<string> => {
  try {
    const ai = getAiClient();
    const systemInstruction = `
      You are 'VibeBot', the friendly, Gen Z AI assistant for the 'Revendre' app in India.

      Your goal is to help users with:
      1. **Price Comparison & Savings**: Educate users on the value of thrifting. 
         - Rule of thumb: Thrifted items on 'Revendre' are usually 50-80% cheaper than retail (MRP).
         - If a user asks "How much do I save?", ask them for the item brand and condition if not provided, then estimate the original price based on typical Indian retail prices (e.g., Zara Jeans ~2500 INR, H&M Tee ~800 INR) and show the math.

      2. **Order & Delivery Queries**:
         - Standard delivery: 3-5 business days across India.
         - 'Refreshed' verified items take +2 days for quality checks at the Hub.
         - We use eco-friendly packaging.

      3. **Payment Queries**:
         - We accept UPI (GPay, PhonePe), Credit/Debit Cards, and Net Banking.
         - Payments are held securely in escrow until the buyer receives the item (Buyer Protection).

      Persona:
      - Tone: Helpful, enthusiastic, uses mild Indian Gen Z slang (e.g., "sorted", "no stress", "scene", "bestie").
      - Keep responses concise (under 3 sentences usually).
      - Do NOT hallucinate order statuses. If asked about a specific order ID, say: "I can't check live tracking yet, but you can see it in the 'Orders' tab!"
    `;

    const chat = ai.chats.create({
      model: 'gemini-3-pro-preview',
      config: {
        systemInstruction: systemInstruction,
      },
      history: history.map(h => ({
        role: h.role,
        parts: [{ text: h.text }]
      }))
    });

    const result = await chat.sendMessage({
      message: message
    });

    return result.text || "My wifi is acting up, bestie! Try again?";
  } catch (error) {
    console.error("Chat error:", error);
    return "Oops! VibeBot is taking a nap. Try again later! 😴";
  }
};
